 r=read(P/'report.json');s=read(D/'sealed.json');p=read(D/'plan.json');a=p['primary'];pair=r['paired'][a+'-NativeG6'];source=r['paired'][a+'-Source'];controls=['MotionReflectedFusion','AppearanceFocusFusion','AppearanceReflectedFusion','WrongTimeMotionFusion','BothFocusFusion']
